        translation 3 1.192195 0
        shape Shape {
          geometry Box {
            size 1 1 1
          }
        }
      }
    }
  ]
}

DEF TS TimeSensor {
  loop TRUE
}

DEF SC Script {
  inputOnly      SFTime  tick
  outputOnly     SFVec3f lv
  initializeOnly SFFloat s0 9.466848e8

  url "ecmascript:
var done = [ ];
function tick (v)
{
  if (s0 < 0) s0 = v;
